const later = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

Promise.allSettled([later(20, "a"), Promise.reject(new Error("b")), "c"]).then((results) => {
  for (const result of results) {
    console.log(result.status, result.value ?? result.reason.message);
  }
});

Promise.all([]).then((list) => console.log("empty", list.length));
